// Retell llama aquí ANTES de descolgar cada llamada entrante, y lo que se conteste
// decide quién la atiende: rechazarla (número bloqueado), pasarla a otro agente (VIP)
// o dejar a Lucía con lo que ya sabemos de quien llama.
//
// Regla de todo el workflow: FALLA HACIA LUCÍA. Si algo sale mal aquí, la respuesta
// es "sin cambios" y Retell atiende con el agente que tenga el número. Nunca se rechaza
// una llamada por un error nuestro: prefiero dejar pasar a un spammer que colgarle a un
// cliente.
const cfg = $json;
const headers = cfg.headers || {};

// La firma se calcula sobre los bytes EXACTOS, igual que en `VOZ · Nota de llamada`
// (ver allí por qué hay tantas formas de recibir el cuerpo).
let raw = null, forma = 'ausente';
let b = cfg.body;
try {
  const hook = $('Webhook · POST /retell-inbound').first();
  if (hook && hook.json && hook.json.body !== undefined) b = hook.json.body;
  const bin = (hook && hook.binary) || {};
  const dato = bin.data || bin.body || Object.values(bin)[0];
  if (dato && dato.data) { raw = Buffer.from(dato.data, 'base64').toString('utf8'); forma = 'binario_webhook'; }
} catch (e) { /* sin webhook */ }
if (!raw) {
  if (typeof b === 'string') { raw = b; forma = 'string'; }
  else if (b && b.type === 'Buffer' && Array.isArray(b.data)) { raw = Buffer.from(b.data).toString('utf8'); forma = 'buffer_json'; }
  else if (b && typeof b === 'object') { forma = 'objeto_parseado'; }
}
let cuerpo = {};
if (raw) { try { cuerpo = JSON.parse(raw); } catch (e) { cuerpo = {}; } }
else if (b && typeof b === 'object') { cuerpo = b; }

const cruda = String(headers['x-retell-signature'] || '');
const hex = cruda.match(/[0-9a-fA-F]{64}/);
const mt = cruda.match(/v=(\d+)/);
const ts = mt ? mt[1] : '';

const llamada = cuerpo.call_inbound || {};
// Mismo criterio que el despachador y la nota: un español sin el 34 es el mismo número.
const aE164 = (x) => { const g = String(x || '').replace(/[^\d]/g, ''); return /^[6789]\d{8}$/.test(g) ? `34${g}` : g; };
return [{ json: {
  evento: String(cuerpo.event || ''),
  llamada,
  telefono: aE164(llamada.from_number),
  directus_base_url: cfg.directus_base_url,
  agente_pasarela: String(cfg.agente_pasarela || '').startsWith('__') ? '' : String(cfg.agente_pasarela || ''),
  forma_cuerpo: forma,
  _raw: raw || '', _ts: ts, _sig: hex ? hex[0] : cruda.trim(),
  // Lo firmado es CUERPO + MARCA DE TIEMPO, en ese orden (confirmado en call_analyzed).
  _firmado: raw && ts ? `${raw}${ts}` : '',
  _secret: String(cfg.retell_api_key || ''),
  _require_signature: String(cfg.require_signature).toLowerCase() === 'true',
} }];

// Sin firma válida no se consulta NADA: la respuesta de este webhook lleva el nombre
// del cliente y el teléfono de su gestor, y sin verificar cualquiera podría preguntar
// por un número y enterarse. El veredicto sale siempre, como en la nota de llamada.
const d = $json;
const a = String(d._hmac || ''), b = String(d._sig || '');
let igual = a.length > 0 && a.length === b.length;
for (let i = 0; i < Math.max(a.length, b.length); i++) if ((a.charCodeAt(i) || 0) !== (b.charCodeAt(i) || 0)) igual = false;
let firma = 'invalida', firma_motivo = null;
if (!d._secret || d._secret.startsWith('REPLACE_')) { firma = 'no_verificada'; firma_motivo = 'no hay RETELL_API_KEY en el tenant'; }
else if (!b) { firma = 'ausente'; firma_motivo = 'sin x-retell-signature'; }
else if (!d._raw) { firma = 'no_verificada'; firma_motivo = `sin cuerpo crudo (${d.forma_cuerpo})`; }
else if (igual) {
  const edad = Math.abs(Date.now() - Number(d._ts || 0));
  firma = edad <= 5 * 60 * 1000 ? 'valida' : 'caducada';
  if (firma === 'caducada') firma_motivo = `marca de tiempo a ${Math.round(edad / 1000)}s`;
} else { firma_motivo = 'el HMAC no coincide'; }

const procesar = d.evento === 'call_inbound' && (firma === 'valida' || !d._require_signature);
const salida = { ...d, firma, firma_motivo, procesar };
for (const k of ['_raw', '_sig', '_secret', '_hmac', '_firmado']) delete salida[k];
return [{ json: salida }];

// Firma inválida, u otro evento (un SMS entrante también pasa por aquí). Se contesta
// "sin cambios": Retell sigue con el agente del número y no se ha revelado nada.
const d = $json;
return [{ json: { respuesta: d.evento === 'call_inbound' ? { call_inbound: {} } : {},
  decision: 'sin_cambios', motivo: d.evento === 'call_inbound' ? `firma ${d.firma}` : `evento ${d.evento || '?'}`,
  firma_motivo: d.firma_motivo } }];

// La decisión, en este orden: bloqueado -> VIP -> Lucía con contexto.
// Todas las consultas van con neverError: una que falle cuenta como "no sé nada",
// y "no sé nada" nunca rechaza ni desvía -- deja a Lucía.
const d = $('Code · Verificar firma').first().json;
const filas = (nombre) => {
  try {
    const r = $(nombre).first().json || {};
    const code = r.statusCode || 0;
    return (code >= 200 && code < 300 && r.body && Array.isArray(r.body.data)) ? r.body.data : null;
  } catch (e) { return null; }
};
// Mismo criterio que el despachador: un español tecleado sin el 34 es el mismo número.
const aE164 = (x) => { const g = String(x || '').replace(/[^\d]/g, ''); return /^[6789]\d{8}$/.test(g) ? `34${g}` : g; };
const tel = d.telefono;

const bloqueados = filas('HTTP · Bloqueados');
if (tel && bloqueados && bloqueados.some((b) => aE164(b.telefono) === tel)) {
  return [{ json: { decision: 'rechazada', respuesta: { call_inbound: { reject: true } } } }];
}

const contacto = (filas('HTTP · Contacto') || [])[0] || null;
const servicios = (filas('HTTP · Servicios') || []).map((s) => s.name).filter(Boolean);

// Retell espera las variables como texto. Vacías si no se sabe: el prompt tiene que
// tolerar que no estén, porque en una webcall de prueba tampoco llegarán.
const variables = {
  telefono: tel,
  nombre_cliente: (contacto && contacto.first_name) || '',
  empresa_cliente: (contacto && contacto.company) || '',
  es_cliente: contacto ? 'si' : 'no',
  servicios: servicios.join(', '),
  es_vip: 'no',
  gestor_nombre: '',
};

const g = contacto && contacto.gestor_id;
const gestorOk = g && String(g.status || '').toLowerCase() === 'active' && (g.phone_normalized || g.phone);
if (contacto && contacto.trato === 'vip') {
  variables.es_vip = 'si';
  variables.gestor_nombre = (g && g.first_name) || '';
  // Solo se desvía si TODO está: pasarela configurada y un gestor activo con teléfono.
  // Un VIP sin eso lo atiende Lucía -- sabiendo que es VIP --, nunca se queda colgado.
  if (d.agente_pasarela && gestorOk) {
    variables.destino_transferencia = `+${aE164(g.phone_normalized || g.phone)}`;
    return [{ json: { decision: 'vip_pasarela', respuesta: { call_inbound: {
      override_agent_id: d.agente_pasarela, dynamic_variables: variables,
      metadata: { aegora_decision: 'vip_pasarela' } } } } }];
  }
  return [{ json: { decision: 'vip_sin_pasarela',
    motivo: !d.agente_pasarela ? 'tenant sin RETELL_AGENTE_PASARELA' : 'gestor sin asignar, inactivo o sin teléfono',
    respuesta: { call_inbound: { dynamic_variables: variables, metadata: { aegora_decision: 'vip_sin_pasarela' } } } } }];
}
return [{ json: { decision: contacto ? 'cliente' : 'desconocido',
  respuesta: { call_inbound: { dynamic_variables: variables, metadata: { aegora_decision: contacto ? 'cliente' : 'desconocido' } } } } }];
